function EXTRA(R,ICON){
 /* hook: the same battery, lamps bright with the lights alone and dim while the engine cranks */
 ICON.ctLampOn=(x,y)=>`<g transform="translate(${x-190} ${y-80})">${CT_box(0,0,380,160,{fill:'#FFFFFF',st:BLU,sw:3,r:18})}${CT_T(20,36,'lights only: bright',{fs:24,fw:800,fill:BLU})}${CT_L(40,70,40,122,CT_INK,4)}${CT_L(56,84,56,108,CT_INK,7)}${CT_T(24,148,'12 V',{fs:22,fw:700,fill:CT_MUT})}${CT_lamp(230,96,1)}${CT_lamp(320,96,1)}</g>`;
 ICON.ctLampDim=(x,y)=>`<g transform="translate(${x-190} ${y-80})">${CT_box(0,0,380,160,{fill:'#FFFFFF',st:ORG,sw:3,r:18})}${CT_T(20,36,'engine cranking: dim',{fs:24,fw:800,fill:ORG})}${CT_L(40,70,40,122,CT_INK,4)}${CT_L(56,84,56,108,CT_INK,7)}${CT_T(24,148,'12 V',{fs:22,fw:700,fill:CT_MUT})}${CT_lamp(230,96,0)}${CT_lamp(320,96,0)}${CT_T(130,110,'?',{fs:48,fw:800,a:'middle',fill:ORG})}</g>`;
 /* recap pictures: each fills most of its card (about 420 × 330) */
 ICON.ctLaws=(x,y)=>`<g transform="translate(${x-210} ${y-165})"><rect x="-14" y="20" width="448" height="320" rx="18" fill="#EDF2FF"/>${[[70,'res','v = Ri'],[180,'coil','v = L di/dt'],[290,'cap','i = C dv/dt']].map(([yy,k,t])=>`<g transform="translate(-6 ${yy}) scale(1.7)">${k==='res'?CT_res(0,120,0,BLU,4):k==='coil'?CT_coil(0,120,0,BLU,4):CT_cap(0,120,0,BLU,4)}</g>`+CT_T(212,yy+14,t,{fs:40,fw:800,fill:BLU})).join('')}</g>`;
 ICON.ctJump=(x,y)=>`<g transform="translate(${x-210} ${y-165})">${CT_L(10,140,410,140,CT_AX,2)}${CT_poly(CT_iC.map(([t,i])=>[10+(t+5)*400/45,140-i*10]),GRN,5)}${CT_T(14,20,'iC can jump',{fs:26,fw:800,fill:GRN})}${CT_L(10,310,410,310,CT_AX,2)}${CT_poly(CT_vC.map(([t,v])=>[10+(t+5)*400/45,310-v*12]),ORG,6)}${CT_T(14,200,'vC cannot',{fs:26,fw:800,fill:ORG})}</g>`;
 ICON.ctSrc=(x,y)=>`<g transform="translate(${x-210} ${y-165})">${CT_vs(70,60,40)}${CT_T(140,70,'independent',{fs:26,fw:800,fill:ORG})}${CT_dia(70,170,44,GRN,'i')}${CT_T(140,180,'dependent',{fs:26,fw:800,fill:GRN})}${CT_L(20,300,400,300,CT_AX,2)}${CT_L(20,240,400,240,ORG,3,'stroke-dasharray="8 6"')}${CT_L(20,240,400,290,BLU,5)}${CT_T(400,232,'ideal 12 V',{fs:22,fw:700,a:'end',fill:ORG})}${CT_T(400,326,'practical sags',{fs:22,fw:700,a:'end',fill:BLU})}</g>`;
}
